ock></fo:table-cell></fo:table-row><fo:table-row height="25px"><fo:table-cell><fo:block font-family="Montserrat" font-size="8pt" color="black" text-align="right" font-weight="bold" vertical-align="middle">   Nombre:               </fo:block></fo:table-cell><fo:table-cell number-columns-spanned="3"><fo:block font-family="Montserrat" font-size="8pt" color="black" text-align="left" vertical-align="middle">   $Nombre$               </fo:block></fo:table-cell></fo:table-row></fo:table-body></fo:table></fo:block></fo:static-content><!--Pie de Pagina--><fo:static-content flow-name="xsl-region-after"><fo:block line-height="8pt" space-before.optimum="1.5pt" space-after.optimum="1.5pt" text-align="right"><fo:inline font-size="8pt"><fo:page-number /></fo:inline><fo:inline font-size="8pt">/</fo:inline><fo:inline font-size="8pt"><!--<fo:page-number-citation-last/>--><fo:page-number-citation ref-id="NumPDF" /></fo:inline></fo:block></fo:static-content><!--Cuerpo de la pagina--><fo:flow flow-name="xsl-region-body" font-family="Montserrat" font-size="9pt" color="black"><fo:block break-before="page"><!--Tabla 2--><fo:table width="17.5cm" border-collapse="separate"><fo:table-column column-width="1.25cm" /><fo:table-column column-width="15.0cm" /><fo:table-column column-width="1.25cm" /><fo:table-body><!--Espacio--><fo:table-row height="4px" vertical-align="middle"><fo:table-cell /><fo:table-cell /><fo:table-cell /></fo:table-row><fo:table-row height="10px" vertical-align="middle"><fo:table-cell /><fo:table-cell><fo:block font-family="Montserrat" font-size="9pt" color="black" text-align="center" font-weight="bold" vertical-align="middle">   Resolución(es) e importe(s) considerado(s) para el pago               </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="18px" vertical-align="middle"><fo:table-cell /><fo:table-cell><!--Tabla interior 1--><fo:table width="15.0cm" vertical-align="bottom" text-align="right" border-collapse="separate" border-width="thin" border-style="solid" border-color="#000000"><fo:table-column column-width="9.0cm" /><fo:table-column column-width="3.0cm" /><fo:table-column column-width="3.0cm" /><fo:table-body><fo:table-row height="18px" vertical-align="middle"><fo:table-cell border-width="thin" border-style="solid" background-color="#FFFFFF"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="center" font-weight="bold" vertical-align="middle">           Número de resolución ó Referencia                       </fo:block></fo:table-cell><fo:table-cell border-width="thin" border-style="solid" background-color="#FFFFFF"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="center" font-weight="bold" vertical-align="middle">           Importe actualizado *                       </fo:block></fo:table-cell><fo:table-cell border-width="thin" border-style="solid" background-color="#FFFFFF"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="center" font-weight="bold" vertical-align="middle">           Importe a pagar                       </fo:block></fo:table-cell></fo:table-row><Documento /><fo:table-row height="18px"><fo:table-cell border-width="thin" border-style="solid"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="center" font-weight="bold" vertical-align="middle">           Totales                       </fo:block></fo:table-cell><fo:table-cell border-width="thin" border-style="solid"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="right" font-weight="bold" vertical-align="middle">           $ImporteActualizadoT$                       </fo:block></fo:table-cell><fo:table-cell border-width="thin" border-style="solid"><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="right" font-weight="bold" vertical-align="middle">           $ImporteAPagarT$                       </fo:block></fo:table-cell></fo:table-row></fo:table-body></fo:table><!--Fin Tabla interior 1--></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="7px" vertical-align="middle"><fo:table-cell /><fo:table-cell><fo:block font-family="Montserrat" font-size="7pt" color="black" text-align="left" font-weight="bold" vertical-align="middle">   * El(los) importe(s) se encuentra(n) actualizado(s) al: <fo:inline font-family="Montserrat">$Fecha$</fo:inline></fo:block></fo:table-cell><fo:table-cell /></fo:table-row></fo:table-body></fo:table><!--Hasta aqui voy--><fo:table width="17.5cm" border-collapse="separate"><fo:table-column column-width="17.5cm" /><fo:table-body><fo:table-row height="0.2cm"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell><fo:block text-align="center" font-family="Montserrat" font-size="8pt">   Observaciones:               </fo:block></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell><fo:table width="17.5cm" border-collapse="separate" text-align="center" vertical-align="middle"><fo:table-column column-width="0.5cm" /><fo:table-column column-width="16.5cm" /><fo:table-column column-width="0.5cm" /><fo:table-body><fo:table-row height="2.0cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell border-style="solid" border-width="0.5px" border-color="#000000"><fo:block margin-left="5px" text-align="justify" font-family="Montserrat" font-size="8pt">           $Observaciones$                       </fo:block></fo:table-cell><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row></fo:table-body></fo:table></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell><!--Empiezan las leyendas--><fo:table width="17.5cm" border-collapse="separate" text-align="center" vertical-align="middle" font-family="Montserrat" font-size="6.3pt"><fo:table-column column-width="0.5cm" /><fo:table-column column-width="16.5cm" /><fo:table-column column-width="0.5cm" /><fo:table-body><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell><fo:block text-align="justify">           El(los) importe(s) de las contribuciones y/o aprovechamientos por el(los) cual(es) se emite el presente  formato, se encuentra(n) actualizado(s) a la fecha de su emisión; dicho(s) importe(s) deberá(n) actualizarse con motivo de la publicación de un nuevo Índice Nacional de Precios al Consumidor en el  Diario Oficial de la Federación o a la entrada en vigor de una nueva tasa de recargos; en términos de lo dispuesto por los artículos <fo:inline font-family="Montserrat">17-A</fo:inline> y <fo:inline font-family="Montserrat">21</fo:inline> del Código Fiscal de la Federación, una vez efectuado el pago, se aplicará en el orden establecido en el artículo <fo:inline font-family="Montserrat">20</fo:inline> del citado Código.                       </fo:block></fo:table-cell><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell /><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell><fo:block text-align="justify">           El importe a pagar no te libera del pago de gastos de ejecución y extraordinarios generados durante los actos de cobro realizados. Para validar el pago total del adeudo, comunícate a MarcaSAT: <fo:inline font-family="Montserrat">55 627 22 728</fo:inline>, opción <fo:inline font-family="Montserrat">9</fo:inline>, seguida de la opción <fo:inline font-family="Montserrat">1</fo:inline>, o acude a la Administración Desconcentrada de Servicios al Contribuyente que te corresponda.                       </fo:block></fo:table-cell><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell /><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell><fo:block text-align="justify">           Si pagas después de la fecha de vigencia señalada en la sección de línea de captura, deberás obtener un nuevo "Formato para Pago de Contribuciones Federales" de forma gratuita en sat.gob.mx, o a través de MarcaSAT: <fo:inline font-family="Montserrat">55 627 22 728</fo:inline>, opción <fo:inline font-family="Montserrat">9</fo:inline>, seguida de la opción <fo:inline font-family="Montserrat">1</fo:inline>, o bien, acudir a las oficinas de la Administración Desconcentrada de Servicios al Contribuyente que corresponda a tu domicilio fiscal.                       </fo:block></fo:table-cell><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell /><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell /><fo:table-cell><fo:block text-align="justify">           El pago con cheque certificado, de caja o personal de la misma institución de crédito ante la cual se efectúa el pago, se entenderá realizado en las fechas que señala la Regla <fo:inline font-family="Montserrat">2.1.19.</fo:inline> de la Resolución Miscelánea Fiscal para <fo:inline font-family="Montserrat">2020</fo:inline>, publicada en el Diario Oficial de la Federación el <fo:inline font-family="Montserrat">28</fo:inline> de diciembre de <fo:inline font-family="Montserrat">2019</fo:inline>.                       </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell /><fo:table-cell /><fo:table-cell /></fo:table-row><fo:table-row><fo:table-cell /><fo:table-cell><fo:block text-align="justify">           Si deseas modificar o corregir tus datos personales, utiliza nuestros servicios de internet en la Administración Desconcentrada de Servicios al Contribuyente que corresponda para recibir asesoría gratuita.                       </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell /><fo:table-cell /><fo:table-cell /></fo:table-row><fo:table-row><fo:table-cell /><fo:table-cell><fo:block text-align="justify">           Tus datos personales son incorporados y protegidos en los sistemas institucionales del SAT, de conformidad con lo establecido por el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales, así como Lineamientos de Protección de Datos Personales y con las diversas disposiciones fiscales y legales sobre confidencialidad y protección de datos, a fin de ejercer las facultades conferidas a la autoridad fiscal.                       </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell /><fo:table-cell /><fo:table-cell /></fo:table-row><fo:table-row><fo:table-cell /><fo:table-cell><fo:block text-align="justify">           Para cualquier aclaración, con gusto te atenderemos a través del MarcaSAT: <fo:inline font-family="Montserrat">55 627 22 728</fo:inline>, opción <fo:inline font-family="Montserrat">9</fo:inline>, seguida de la opción <fo:inline font-family="Montserrat">1</fo:inline>, o acude a la Administración Desconcentrada de Servicios al Contribuyente que te corresponde.                       </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell /><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row><fo:table-row><fo:table-cell /><fo:table-cell><fo:block text-align="justify" font-style="italic">           Por favor verifique que la línea de captura y el importe que aparece en el comprobante de pago que emita la Institución de Crédito autorizada, coincidan con la información impresa en este formato de pago.                       </fo:block></fo:table-cell><fo:table-cell /></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block text-align="left" /></fo:table-cell><fo:table-cell /><fo:table-cell><fo:block text-align="left" /></fo:table-cell></fo:table-row></fo:table-body></fo:table><!--Terminan las leyendas--></fo:table-cell></fo:table-row><fo:table-row height="0.2cm"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row><fo:table-row><!--Linea de captura--><fo:table-cell><fo:table width="17.5cm"><fo:table-column column-width="17.5cm" /><fo:table-body><fo:table-row keep-with-next="always"><fo:table-cell><fo:table width="17.5cm" order-collapse="separate" color="black" display-align="center" break-before="column" table-layout="fixed" padding="5pt 5pt 5pt 5pt" border="0.5px solid black"><fo:table-column column-width="2.6cm" /><fo:table-column column-width="7.8cm" /><fo:table-column column-width="2.3cm" /><fo:table-column column-width="4.8cm" /><fo:table-body><fo:table-row keep-with-next="always"><fo:table-cell number-columns-spanned="4"><fo:block font-family="Montserrat" text-align="center" font-weight="bold" font-size="11pt">     SECCIÓN LÍNEA DE CAPTURA                               </fo:block></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always" height="0.3cm"><fo:table-cell number-columns-spanned="4"><fo:block /></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always"><fo:table-cell number-columns-spanned="4"><fo:block font-family="Montserrat" text-align="justify" font-size="9pt">     El importe deberá ser pagado en las Instituciones de Crédito autorizadas, utilizando para tal efecto la línea de captura que se indica a continuación:                               </fo:block></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always" height="0.3cm"><fo:table-cell number-columns-spanned="4"><fo:block /></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always"><fo:table-cell><fo:block font-family="Montserrat" font-size="9pt" text-align="left"><fo:inline>Línea de </fo:inline></fo:block><fo:block font-family="Montserrat" font-size="9pt" text-align="left"><fo:inline>Captura: </fo:inline></fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Menlo" font-size="12pt" letter-spacing="1px" text-align="left" font-weight="bold">     $NumLC$                               </fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Montserrat" font-size="9pt" text-align="left">     Importe total a pagar:                               </fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Montserrat" font-size="14pt" text-align="right" font-weight="bold">     $ImporteAPagarT$                               </fo:block></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always" height="0.3cm"><fo:table-cell number-columns-spanned="4"><fo:block /></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always"><fo:table-cell><fo:block font-family="Montserrat" font-size="9pt" text-align="left">     Vigente hasta:                               </fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Montserrat" font-size="9pt" text-align="left" font-weight="bold">     $FechaVigencia$                               </fo:block></fo:table-cell><fo:table-cell number-columns-spanned="2"><fo:block font-family="Montserrat" font-size="7pt" text-align="right"> 									$Leyenda$ 								</fo:block></fo:table-cell></fo:table-row></fo:table-body></fo:table></fo:table-cell></fo:table-row><fo:table-row height="0.4cm" keep-with-next="always"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row><fo:table-row keep-with-next="always"><fo:table-cell><CodigoBarrasDetalle /></fo:table-cell></fo:table-row></fo:table-body></fo:table><!--Fin linea de captura--></fo:table-cell></fo:table-row><fo:table-row height="0.3cm"><fo:table-cell><fo:block /></fo:table-cell></fo:table-row></fo:table-body></fo:table></fo:block><fo:block space-before.optimum="1.5pt" space-after.optimum="1.5pt" keep-together="always" id="NumPDF" line-height="1pt" font-size="1pt" /></fo:flow></fo:page-sequence>'
WHERE NombreTemplate = 'LineaCaptura' and Version ='1'

