antia" font-size="9pt" color="black" text-align="left" vertical-align="middle"> 								$ALR$ 							</fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Constantia" font-size="9pt" color="black" text-align="left" font-weight="bold" vertical-align="middle"> 								Número de documento: 							</fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Arial" font-size="9pt" color="black" text-align="left" vertical-align="middle"> 								$FolioLC$ 							</fo:block></fo:table-cell></fo:table-row><fo:table-row height="18px"><fo:table-cell><fo:block font-family="Constantia" font-size="9pt" color="black" text-align="left" font-weight="bold" vertical-align="middle"> 								R.F.C.: 							</fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Arial" font-size="9pt" color="black" text-align="left" vertical-align="middle"> 								$RFC$ 							</fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Constantia" font-size="9pt" color="black" text-align="left" font-weight="bold" vertical-align="middle"> 								Fecha y hora de emisión: 							</fo:block></fo:table-cell><fo:table-cell><fo:block font-family="Arial" font-size="9pt" color="black" text-align="left" vertical-align="middle"> 								$FechaYHora$ 							</fo:block></fo:table-cell></fo:table-row><fo:table-row height="18px"><fo:table-cell><fo:block font-family="Constantia" font-size="9pt" color="black" text-align="left" font-weight="bold" vertical-align="middle"> 								Nombre: 							</fo:block></fo:table-cell><fo:table-cell number-columns-spanned="3"><fo:block font-family="Constantia" font-size="9pt" color="black" text-align="left" vertical-align="middle"> 								$Nombre$ 							</fo:block></fo:table-cell></fo:table-row></fo:table-body></fo:table></fo:block></fo:static-content><!--Pie de Pagina--><fo:static-content flow-name="xsl-region-after"><fo:block line-height="8pt" space-before.optimum="1.5pt" space-after.optimum="1.5pt" text-align="right"><fo:inline font-size="8pt"><fo:pa